let out = $input.first().json.output;
if (typeof out === 'string') {
  try {
    out = JSON.parse(out);
  } catch (e) {
    out = { reply: out };
  }
}
if (out && typeof out.output === 'object' && out.output !== null) out = out.output;
out = out || {};

const reply = typeof out.reply === 'string' && out.reply.trim()
  ? out.reply.trim()
  : 'Xin lỗi, mình chưa trả lời được câu này. Bạn thử hỏi lại theo cách khác nhé.';
const suggestions = (Array.isArray(out.suggestions) ? out.suggestions : [])
  .filter((s) => typeof s === 'string' && s.trim())
  .map((s) => s.trim())
  .slice(0, 4);
const product_ids = [...new Set((Array.isArray(out.products) ? out.products : [])
  .map((p) => (typeof p === 'string' ? p : p?.image_id))
  .filter((id) => typeof id === 'string')
  .map((id) => id.trim().replace(/^\[|\]$/g, ''))
  .filter((id) => /^[\w.-]{1,64}$/.test(id)))].slice(0, 6);

return [{ json: { reply, suggestions, product_ids } }];

