parameters.jsCode:
const { reply, suggestions } = $('Đọc câu trả lời').first().json;
let products = $input.first().json.products;
if (typeof products === 'string') products = JSON.parse(products);
if (!Array.isArray(products)) products = [];

const s = (v) => (typeof v === 'string' ? v : v == null ? '' : String(v));
return [{
  json: {
    reply,
    suggestions,
    products: products.map((p) => ({
      image_id: s(p.image_id),
      title: s(p.title),
      author: s(p.author),
      publisher: s(p.publisher),
      supplier: s(p.supplier),
      image_url: s(p.image_url),
      product_url: s(p.product_url),
    })),
  },
}];

let cfg = $input.first().json.cfg || {};
if (typeof cfg === 'string') cfg = JSON.parse(cfg);
const posInt = (v, d) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : d;
};
const query = String($('Khi agent gọi tim_sach').first().json.query || '').replace(/\s+/g, ' ').trim().slice(0, 1000);
if (!query) throw new Error('Công cụ tim_sach cần tham số query (mô tả sách cần tìm).');

const norm = (s) => String(s || '')
  .replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/\p{Mn}/gu, '').normalize('NFC')
  .toLowerCase().replace(/\s+/g, ' ').trim();

const embed_model = String(cfg.embed_model || 'gemini-embedding-2').trim();
const embed_dims = posInt(cfg.embed_dims, 768);
const request = { content: { parts: [{ text: query }] }, outputDimensionality: embed_dims };
if (!embed_model.startsWith('gemini-embedding-2')) request.taskType = 'RETRIEVAL_QUERY';

return [{
  json: {
    query,
    query_norm: norm(query),
    embed_model,
    embed_dims,
    top_k: Math.min(posInt(cfg.top_k, 10), 20),
    embed_request: request,
  },
}];

const { embed_request, ...ctx } = $('Tool: chuẩn bị embed').first().json;
const values = $input.first().json.embedding?.values;
if (!Array.isArray(values) || values.length !== ctx.embed_dims) {
  throw new Error(`Embedding sai số chiều: ${Array.isArray(values) ? values.length : 'không có'} (cần ${ctx.embed_dims})`);
}
return [{ json: { ...ctx, text_vec: `[${values.join(',')}]` } }];

let rows = $input.first().json.rows;
if (typeof rows === 'string') rows = JSON.parse(rows);
if (!Array.isArray(rows)) rows = [];
const s = (v) => (typeof v === 'string' ? v : v == null ? '' : String(v));

const books = rows.map((r) => ({
  image_id: s(r.image_id),
  title: s(r.title),
  author: s(r.author),
  publisher: s(r.publisher),
  supplier: s(r.supplier),
  description: s(r.description).replace(/\s+/g, ' ').trim().slice(0, 400),
  score: Math.round((Number(r.score) || 0) * 1000) / 1000,
}));

return [{
  json: {
    query: $('Tool: chuẩn bị embed').first().json.query,
    found: books.length,
    note: books.length ? 'Chỉ giới thiệu các cuốn trong danh sách books, dẫn đúng image_id và tên.' : 'Không tìm thấy sách phù hợp trong kho.',
    books,
  },
}];
